#include <iostream>
#include <string>

int main()
{
    int count = 5;
    short status = 2;
    char letter = 'A';
    std::string s = "ABC";

    int* pCount = &count;
    short* pStatus = &status;
    char* pLetter = &letter;
    std::string* pString = &s;

    std::cout << "Size of int: " << sizeof(count) << " bytes\n";
    std::cout << "Size of short: " << sizeof(status) << " bytes\n";
    std::cout << "Size of char: " << sizeof(letter) << " bytes\n";

    // Verify pointers store non-null valid addresses
    if (pCount != nullptr && pStatus != nullptr && pLetter != nullptr && pString != nullptr)
    {
        std::cout << "All pointers successfully store first-byte addresses.\n";
    }

    return 0;
}

#include <iostream>

int main()
{
    // Step 1: Listing 11.1 variable and pointer declarations
    int count = 5;
    int* pCount = &count;

    // Step 2: Accessing value directly and indirectly
    std::cout << "Direct value of count: " << count << "\n";
    std::cout << "Indirect value via *pCount: " << *pCount << "\n";

    // Step 3: Verifying pCount contains the address of count
    if (pCount == &count)
    {
        std::cout << "pCount holds identical address to &count.\n";
    }

    // Step 4: Indirect modification using (*pCount)++
    (*pCount)++;
    std::cout << "Value of count after (*pCount)++: " << count << "\n";

    // Step 5: Demonstrating multiplication operator usage of *
    double radius = 2.0;
    double area = radius * radius * 3.14159;
    std::cout << "Computed area using multiplication *: " << area << "\n";

    return 0;
}
